ROW.COLUMN:
-- PR 44965 Tilak 26 Aug 10 -- Changed the logic of implementation of threshold Include months with no activity -- 11/24/2006 -- PR 32989 Lookback period changed from 11 to 12 months to calculate the whole year -- -- 12/2/04 vpogrebnov change "@Look_Back_Period - 1" to "@Look_Back_Period" --06/07/2016 Bug 23236260 select INSTN_SEQ_ID, case when @Incl_Mnths_With_No_Actvty = 'N' -- exclude months that have no activity then case when sum(C_CREDIT_CT) >0 then sum(C_CREDIT)/sum(C_CREDIT_CT) else 0 end else -- include months that have no activity sum(C_CREDIT)/count(C_CREDIT_CT)
end as C_AVG_TRANS_AM , case when @Incl_Mnths_With_No_Actvty = 'N' -- exclude months that have no activity then case when sum(D_DEBIT_CT)>0 then sum(D_DEBIT)/sum(D_DEBIT_CT) else 0 end else -- include months that have no activity sum(D_DEBIT)/count(D_DEBIT_CT)
end as D_AVG_TRANS_AM -- 23236260 , case when @Incl_Mnths_With_No_Actvty = 'N' then COALESCE(stddev_samp( decode (C_CREDIT , 0 , null ,C_CREDIT)),0) else COALESCE(stddev_samp(C_CREDIT),0) end as C_STD_DEV , case when @Incl_Mnths_With_No_Actvty = 'N' then COALESCE(stddev_samp( decode (D_DEBIT , 0 , null ,D_DEBIT)),0) else COALESCE(stddev_samp(D_DEBIT),0) end as D_STD_DEV from ( select a.INSTN_SEQ_ID, (a.DOM_WIRE_TRXN_IN_AM + a.FRGN_WIRE_TRXN_IN_AM + a.CHK_TRXN_IN_AM + a.CASH_EQUIV_TRXN_IN_AM + a.CASH_TRXN_IN_AM + a.JRNL_TRXN_IN_AM) as C_CREDIT, case when (a.DOM_WIRE_TRXN_IN_AM + a.FRGN_WIRE_TRXN_IN_AM + a.CHK_TRXN_IN_AM + a.CASH_EQUIV_TRXN_IN_AM + a.CASH_TRXN_IN_AM + a.JRNL_TRXN_IN_AM)<>0 then 1 else 0 end as C_CREDIT_CT , (a.DOM_WIRE_TRXN_OUT_AM + a.FRGN_WIRE_TRXN_OUT_AM + a.CHK_TRXN_OUT_AM + a.CASH_EQUIV_TRXN_OUT_AM + a.CASH_TRXN_OUT_AM + a.JRNL_TRXN_OUT_AM) as D_DEBIT , case when (a.DOM_WIRE_TRXN_OUT_AM + a.FRGN_WIRE_TRXN_OUT_AM + a.CHK_TRXN_OUT_AM + a.CASH_EQUIV_TRXN_OUT_AM + a.CASH_TRXN_OUT_AM + a.JRNL_TRXN_OUT_AM)<>0 then 1 else 0 end as D_DEBIT_CT from @MINER@.CLIENT_BANK_SMRY_MNTH a where a.MNTH_SMRY_START_DT <= (select k.CLNDR_DT from @MANTAS@.KDD_CAL k where k.MNTH_BNDRY_CD = 'ED2' and k.CLNDR_NM ='SYSCAL') and a.MNTH_SMRY_START_DT >= (select add_months(f_trunc_date(k.CLNDR_DT, 'MM'),-@Look_Back_Period) from @MANTAS@.KDD_CAL k where k.MNTH_BNDRY_CD = 'ED1' and k.CLNDR_NM = 'SYSCAL') ) group by INSTN_SEQ_ID
